html, body {  
    text-align: center;  
    background-color: #FFFFFF; 
    margin: auto;
    padding: 10px;
}  
canvas {
  margin: 10px auto;
  width:100%;
  display: block;
  border: solid 13px black;
  padding: 26px 26px;
  box-shadow: -6px 6px 6px gray;
}

/* Auto-hidden controls */
input, select, button, textarea, label, fieldset,
.dg, .lil-gui, .qs_main, .opc-container, .opc-gui, .quicksettings, .p5DomElement {
    display: none !important;
    visibility: hidden !important;
    opacity: 0 !important;
    pointer-events: none !important;
    position: absolute !important;
    left: -9999px !important;
    top: -9999px !important;
    width: 0px !important;
    height: 0px !important;
}
